import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int ws = s.nextInt(), wo = s.nextInt(), wp = s.nextInt(), minEach = s.nextInt(), n = s.nextInt();
        String best = "NONE";
        int top = - 1;
        for (int i = 0; i < n; i++) {
            String name = s.next();
            int standards = s.nextInt(), operations = s.nextInt(), performance = s.nextInt();
            if (standards < minEach || operations < minEach || performance < minEach) {
                System.out.println(name + " DISQUALIFIED");
                continue;
            }
            int total = standards * ws + operations * wo + performance * wp;
            System.out.println(name + " " + total);
            if (total > top) {
                top = total;
                best = name;
            }
        }
        System.out.println(top < 0 ? "PICK NONE" : "PICK " + best + " " + top);
    }
}

